// Addresses of the guides in each language (plan item 5, 2026-11-14):
//
//   /guides/{hub}/{category}/{article}   e.g. /guides/przewodnik/kompresuj-pdf/jak-skutecznie-skompresowac-pdf-online
//
// {hub} is lib/guides-slugs.ts, {category} and {article} come from lib/guide-category-slugs.ts and
// lib/guide-article-slugs.ts (generated by scripts/build-guide-url-slugs.mts, never rewritten).
// English keeps the original ids, so English addresses did not change. Every other language used
// the English category and article ids until 2026-11-14; those addresses are still recognised
// (`legacy: true`): next.config.ts redirects them with a 308, and the pages do too as a fallback.
//
// Kept free of guide content so client components can use it; breadcrumbs import only the category
// half (lib/guide-category-urls.ts), the language switcher loads this module when it is used.

import type { Locale } from '@/lib/i18n';
import { getLocaleSegment } from '@/lib/guides-slugs';
import { GUIDE_ARTICLE_SLUGS } from '@/lib/guide-article-slugs';
import { categorySegment, normalizeSegment, resolveCategorySegment } from '@/lib/guide-category-urls';

export { categorySegment, resolveCategorySegment };

/** The localized address segment of an article (identified by its English slug). */
export function articleSegment(locale: Locale, category: string, slug: string): string {
  return GUIDE_ARTICLE_SLUGS[category]?.[slug]?.[locale] ?? slug;
}

export function guideHubPath(locale: Locale): string {
  return `/guides/${getLocaleSegment(locale)}`;
}

export function guideCategoryPath(locale: Locale, category: string): string {
  return `${guideHubPath(locale)}/${categorySegment(locale, category)}`;
}

export function guideArticlePath(locale: Locale, category: string, slug: string): string {
  return `${guideCategoryPath(locale, category)}/${articleSegment(locale, category, slug)}`;
}

/** The same path with every segment percent-encoded — for HTTP headers (redirects), which must be ASCII. */
export function encodePath(path: string): string {
  return path.split('/').map((s) => encodeURIComponent(s)).join('/');
}

/** Which article of `category` an address segment names in this language (see resolveCategorySegment). */
export function resolveArticleSegment(locale: Locale, category: string, segment: string): { slug: string; legacy: boolean } | null {
  const articles = GUIDE_ARTICLE_SLUGS[category];
  if (!articles) return null;
  const s = normalizeSegment(segment);
  for (const [slug, names] of Object.entries(articles)) {
    if ((names[locale] ?? slug).normalize('NFC') === s) return { slug, legacy: false };
  }
  if (articles[s]) return { slug: s, legacy: true };
  return null;
}

/**
 * The same guides address in another language — hub, category and article each translated
 * (the language switcher). An address it cannot read leads to the other language's guides hub.
 */
export function translateGuidePath(pathname: string, to: Locale, from: Locale): string {
  const [, , catSeg, artSeg] = pathname.split('/').filter(Boolean);
  if (!catSeg) return guideHubPath(to);
  const cat = resolveCategorySegment(from, catSeg);
  if (!cat) return guideHubPath(to);
  if (!artSeg) return guideCategoryPath(to, cat.category);
  const art = resolveArticleSegment(from, cat.category, artSeg);
  return art ? guideArticlePath(to, cat.category, art.slug) : guideCategoryPath(to, cat.category);
}
